 public function recommend(array $classification,array $state,array $settings):array{$plan=$classification['search_plan']??array();if(!$plan)return array('products'=>array(),'missing_roles'=>array(),'conditional_roles'=>array(),'plan'=>array(),'diagnostic'=>array('status'=>'no_search_plan'));$groups=array();$candidate_ids=array();$catalogue=array();$roles_payload=array();$conditional_roles=array();$plan_count=count($plan);foreach(array_slice($plan,0,10)as$item){$role=sanitize_key($item['role']??'');if($role==='')continue;$required=!empty($item['required']);$requirements=$item['requirements']??array();if($this->defer_conditional($role,$state,$plan_count)){$conditional_roles[]=$role;$groups[]=array('role'=>$role,'required'=>false,'conditional'=>true,'requirements'=>$requirements,'candidates'=>array());continue;}$limit=$required?8:6;$found=$this->products->search(array('query'=>$item['query'],'role'=>$role,'requirements'=>$requirements,'in_stock'=>true,'limit'=>$limit));$ids=array();$group_candidates=array();foreach($found as$product){$id=(int)($product['id']??0);if(!$id)continue;$candidate_ids[$role][$id]=true;$ids[]=$id;if(!isset($catalogue[$id]))$catalogue[$id]=array('id'=>$id,'name'=>$product['name'],'type'=>$product['type'],'price'=>$product['price_text'],'categories'=>$product['categories'],'attributes'=>$product['attributes'],'description'=>mb_substr((string)($product['description']??$product['short_description']),0,450),'stock'=>$product['stock_status'],'retrieval'=>$product['retrieval']??array());$group_candidates[]=$catalogue[$id];}$groups[]=array('role'=>$role,'required'=>$required,'conditional'=>false,'requirements'=>$requirements,'candidates'=>$group_candidates);$roles_payload[]=array('role'=>$role,'required'=>$required,'requirements'=>$requirements,'candidate_ids'=>$ids);}if(!$candidate_ids){$missing=array_values(array_filter(array_column($groups,'role'),static fn($role)=>!in_array($role,$conditional_roles,true)));return array('products'=>array(),'missing_roles'=>$missing,'conditional_roles'=>array_values(array_unique($conditional_roles)),'plan'=>$groups,'diagnostic'=>array('status'=>'no_relevant_candidates','catalogue_products'=>0,'role_candidates'=>0));}$payload=array('state'=>$state,'products'=>array_values($catalogue),'roles'=>$roles_payload);$payload_json=wp_json_encode($payload);$provider=Orion_AI_Provider_Factory::create($settings,'selection');$prompt='Read each unique product once from products, then match its ID to zero or more supplied roles. Decide semantically from title, description, categories and attributes rather than exact query words. Select only candidate_ids allowed for that role. Reject contradictory or unsupported candidates. A roller sleeve may satisfy roller only as a partial accessory and the reason must say a compatible frame is required. Reuse one product ID across roles only when its supplied text explicitly identifies a set, kit or bundle whose stated contents satisfy every assigned role. Prefer a practical core kit over conditional preparation products. Return JSON only: {"selections":[{"role":"...","product_id":123,"reason":"..."}],"missing_roles":["..."]}.';$result=$provider->chat(array(array('role'=>'system','content'=>$prompt),array('role'=>'user','content'=>$payload_json));$data=!empty($result['ok'])?$this->decode((string)($result['message']['content']??'')):null;$selected=array();$selected_index=array();if(is_array($data))foreach(($data['selections']??array())as$choice){$role=sanitize_key((string)($choice['role']??''));$id=absint($choice['product_id']??0);if(!$role||!$id||empty($candidate_ids[$role][$id]))continue;$product=$this->products->get_product($id);if(!$product||empty($product['in_stock']))continue;if(isset($selected_index[$id])){if(!$this->is_bundle($product))continue;$index=$selected_index[$id];if(!in_array($role,$selected[$index]['kit_roles'],true))$selected[$index]['kit_roles'][]=$role;$reason=sanitize_text_field((string)($choice['reason']??''));if($reason!=='')$select