 private function defer_conditional(string $role,array $state,int $plan_count):bool{if($plan_count<=1)return false;if(!in_array($role,array('primer','cleaner','filler','sandpaper','scraper'),true))return false;$text=strtolower(implode(' ',array_map('strval',array_filter($state,'is_scalar'))));return!preg_match('/\b(new plaster|bare|porous|stain|stained|damage|damaged|crack|cracked|hole|holes|uneven|loose|flaking|dirty|grease|mould|mold)\b/',$text);}
 private function priority(array $product):int{$map=array('primary_coating'=>10,'primary_product'=>10,'roller'=>20,'roller_frame'=>21,'roller_sleeve'=>22,'tray'=>30,'brush'=>40,'masking_tape'=>50,'dust_sheet'=>60,'primer'=>70,'cleaner'=>71,'filler'=>72,'sandpaper'=>73,'scraper'=>74);$values=array_map(static fn($role)=>$map[$role]??80,$product['kit_roles']??array($product['kit_role']??''));return$values?min($values):80;}private function is_bundle(array $product):bool{$text=strtolower((string)($product['name']??'').' '.(string)($product['description']??''));return(bool)preg_match('/\b(set|kit|bundle|complete set)\b/',$text);}private function decode(string $text):?array{$text=trim(preg_replace('/^```(?:json)?\s*|\s*```$/i','',trim($text)));$data=json_decode($text,true);if(is_array($data))return$data;if(preg_match('/\{[\s\S]*\}/',$text,$m)){$data=json_decode($m[0],true);return is_array($data)?$data:null;}return null;}
}
